const hAt = (y) => { const f = (y - C.Y0) / C.SW - 0.5; const i = Math.max(0, Math.min(C.N - 1, f)); const a = Math.floor(i), b = Math.min(C.N - 1, a + 1); return C.H[a] + (C.H[b] - C.H[a]) * (i - a); };
