testButton.addEventListener("click", (e) => { e.stopPropagation(); userTest(); });
stage.addEventListener("keydown", (e) => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); userTest(); } });
stage.addEventListener("pointerenter", () => { if (touring) takeOver(); });
still.addEventListener?.("change", () => { touring = !still.matches; run(); });
const hook = { startTest, get u() { return st.running ? st.u : -1; }, get mode() { return st.mode; } };
window["__neural-precursors-2"] = hook; window.__neuralPrecursors2 = hook;
